import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Legacy and Modern Combat","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/legacy-and-modern.md","filePath":"en/game-design/combat/legacy-and-modern.md"}'),r={name:"en/game-design/combat/legacy-and-modern.md"};function o(s,e,d,c,l,m){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="legacy-and-modern-combat" tabindex="-1">Legacy and Modern Combat <a class="header-anchor" href="#legacy-and-modern-combat" aria-label="Permalink to &quot;Legacy and Modern Combat&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> Numeric examples are prototype hypotheses, not final balance. <strong>Implementation/availability:</strong> not established for these mechanics. <strong>Verification:</strong> documentation review, no playable prototype. <strong>Reviewed:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a> · <a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">Combat Variable Registry</a></p><h2 id="definitions-and-design-status" tabindex="-1">Definitions and design status <a class="header-anchor" href="#definitions-and-design-status" aria-label="Permalink to &quot;Definitions and design status&quot;">​</a></h2><p><strong>Legacy Combat</strong> means classic automatic attack cadence. <strong>Modern Combat</strong> means player-triggered attack cadence. Both begin with explicit target selection (classic double-click is an example); target selection is not their distinguishing feature. Use these names as the primary player-facing terminology. “Reactive” describes earlier proposal history or a defensive response, not a third mode.</p><p>Modern is the <strong>preferred experimental design direction, still Proposed</strong> pending playable prototypes. Legacy remains supported in the proposed design as a competitive fallback for accessibility, familiarity and nostalgia. This does not claim either the new dual-mode framework or its shared actions are already implemented.</p><p>The earlier Accepted automatic baseline remains the recorded foundation for the existing experiment. Batch 05 clarifies the intended future alternative instead of requiring every player to click every swing. It does not silently promote Modern to Accepted or replace the current implementation. Formal acceptance, mode switching and the relationship to existing timing contracts require later decisions.</p><h2 id="shared-economy-different-initiation" tabindex="-1">Shared economy, different initiation <a class="header-anchor" href="#shared-economy-different-initiation" aria-label="Permalink to &quot;Shared economy, different initiation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Legacy</th><th>Modern</th></tr></thead><tbody><tr><td>Target</td><td>Explicitly select first</td><td>Same selection requirement</td></tr><tr><td>Basic initiation</td><td>Next valid automatic weapon swing in valid spatial conditions</td><td>Valid attack input starts the available action immediately; no automatic swing timer governs initiation</td></tr><tr><td>Offensive Special Attack</td><td>Queue for next valid legacy swing; cancel/change only where permitted</td><td>Trigger when available, respecting its preparation and wind-up</td></tr><tr><td>Defensive response</td><td>Immediate manual input, not held for a swing</td><td>Same immediate input subject to action eligibility</td></tr><tr><td>Underlying rules</td><td>Shared weapon physics, reach, resource costs, recovery, armor interaction and learned actions</td><td>Same rules and base numbers</td></tr><tr><td>Main trade-off</td><td>Less temporal control, predictable cadence and opportunities to anticipate</td><td>Precise initiation/release timing and responsibility for sustainable pacing</td></tr><tr><td>Power policy</td><td>No hidden damage penalty or free RNG disadvantage</td><td>No arbitrary hidden stat bonus or free faster attacks</td></tr></tbody></table><p>An immediate start is not an immediate hit. The action still incurs its stamina, wind-up, active and recovery commitments. “Valid” includes availability, target, spatial conditions and resource/recovery rules resolved by the server. Costs for rejected inputs, queue changes and cancellations remain undecided.</p><h2 id="cadence-and-bursts" tabindex="-1">Cadence and bursts <a class="header-anchor" href="#cadence-and-bursts" aria-label="Permalink to &quot;Cadence and bursts&quot;">​</a></h2><p>Legacy cadence should consider weapon recovery/class, handling, current stamina/fatigue and bounded DEX; it must not be defined only by DEX. <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html#legacy-test">Batch 06</a> selects one bounded Experimental cadence formula for three weapons; no final formula is accepted.</p><p>Modern can create greater short-term action density by choosing initiation instead of waiting for an automatic swing. Bursts of <strong>2–3+ actions are illustrative test cases</strong>, not guaranteed legal combos. Repeated actions must respect stamina/recovery; too-fast chaining should degrade performance. <a href="/Syrolands-Public/en/game-design/combat/flow.html">Flow</a> explores sustainable rhythm rather than maximum input rate.</p><p>Both modes use the same action definitions and underlying numbers. Proposed Flow adjustments are explicit state-dependent trade-offs, not an undocumented mode-wide advantage. Their fairness and Legacy competitiveness require playtesting; equal base numbers alone do not prove balance.</p><h2 id="archery-and-ranged-actions" tabindex="-1">Archery and ranged actions <a class="header-anchor" href="#archery-and-ranged-actions" aria-label="Permalink to &quot;Archery and ranged actions&quot;">​</a></h2><p>Basic ranged attacks should not require a timing minigame that disadvantages one mode. Shared accuracy can depend on Archery, range, target movement, shooter movement, aim preparation, weapon handling and fatigue/stamina.</p><table tabindex="0"><thead><tr><th>Ranged case</th><th>Legacy</th><th>Modern</th></tr></thead><tbody><tr><td>Basic shot</td><td>Draw/release follows attack cadence automatically</td><td>Player controls release; stopping/holding aim may improve chance/consistency through shared factors</td></tr><tr><td>Timing-meter SA, such as illustrative Precision Shot</td><td>Prepare/store the same minigame result; release on the next valid ranged cadence</td><td>Complete the same minigame, then execute subject to action rules</td></tr></tbody></table><p>Neither receives a free RNG advantage. Stored-result expiry, target changes, aim movement, cancellation and queue replacement are unresolved; the minigame is not required for all shots or selected as implemented UX.</p><h2 id="authority-and-unresolved-contracts" tabindex="-1">Authority and unresolved contracts <a class="header-anchor" href="#authority-and-unresolved-contracts" aria-label="Permalink to &quot;Authority and unresolved contracts&quot;">​</a></h2><p>The client submits target/action intent. The server validates timing, range, LOS, resources, recovery, actual impact and effects; synchronized information and presentation follow its approved state. Animation completion never authorizes attacks. Input arrival/latency, duplicate/rejected input handling, action overlap, queue expiry, switching modes and accessibility/remapping need explicit contracts. No packet, binding, timer or compensation policy is assigned.</p><p>See <a href="/Syrolands-Public/en/game-design/combat/actions.html">actions</a>, <a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">reach</a>, <a href="/Syrolands-Public/en/game-design/characters/familiarity.html">Familiarity</a> and <a href="/Syrolands-Public/en/game-design/combat/status-and-open-questions.html">combat status</a>.</p>',21)])])}const g=t(r,[["render",o]]);export{p as __pageData,g as default};
